let total = toscalar(IntuneDevices | where TimeGenerated {TimeRange} | summarize dcount(tostring(DeviceId)));
let compliant = toscalar(IntuneDeviceComplianceOrg | where TimeGenerated {TimeRange} | summarize arg_max(TimeGenerated, ComplianceState) by tostring(DeviceId) | where ComplianceState == 'Compliant' | count);
let nonComp = toscalar(IntuneDeviceComplianceOrg | where TimeGenerated {TimeRange} | summarize arg_max(TimeGenerated, ComplianceState) by tostring(DeviceId) | where ComplianceState in ('NonCompliant','Error','Unknown','InGracePeriod') | count);
let enroll = toscalar(IntuneAuditLogs | where TimeGenerated {TimeRange} | where OperationName has 'enroll' | count);
let wipes  = toscalar(IntuneAuditLogs | where TimeGenerated {TimeRange} | where OperationName has_any ('wipe','retire','delete') | count);
print TotalDevices=total, Compliant=compliant, NonCompliant=nonComp, Enrollments=enroll, DestructiveActions=wipes
| extend CompliancePct = round(100.0 * Compliant / iif(TotalDevices==0,1,TotalDevices), 1)

let NetworkAllowlist = _GetWatchlist('NetworkAllowlist') | project IPRange = tostring(column_ifexists('IPRange', SearchKey));
let AllowedRanges = toscalar(NetworkAllowlist | summarize make_list(IPRange));
SigninLogs
| where TimeGenerated {TimeRange}
| where AppDisplayName has_any ('Device Registration','Microsoft Intune','Microsoft Authentication Broker')
| where not(ipv4_is_in_any_range(IPAddress, AllowedRanges))
| summarize Events = count(), Users = dcount(UserPrincipalName), IPs = dcount(IPAddress)
           by Country = tostring(LocationDetails.countryOrRegion)
| order by Events desc
